WITH cleaned AS (SELECT *, TRIM(city) AS clean_city, INITCAP(TRIM(city)) AS city_title FROM customers WHERE signup_date >= DATE '2023-05-23' AND city IS NOT NULL) SELECT id, name, email, country, signup_date, is_active, age, city_title, MIN(credit_limit) OVER (PARTITION BY country, city ORDER BY age, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_credit_limit, SUM(credit_limit) OVER (PARTITION BY country, city ORDER BY age, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_credit_limit, AVG(credit_limit) OVER (PARTITION BY country, city ORDER BY age, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_credit_limit, MAX(age) OVER (PARTITION BY DATE_TRUNC('WEEK', signup_date), city) AS signup_date_period_max_age FROM cleaned WHERE country = 'US'
